import { chain } from "@smithy/core/dist-es/submodules/config/property-provider/chain";
import { memoize } from "@smithy/core/dist-es/submodules/config/property-provider/memoize";
import { fromEnv } from "@smithy/core/dist-es/submodules/config/node-config-provider/fromEnv";
import { fromSharedConfigFiles } from "@smithy/core/dist-es/submodules/config/node-config-provider/fromSharedConfigFiles";
import { fromStatic } from "@smithy/core/dist-es/submodules/config/node-config-provider/fromStatic";
export const loadConfig = ({ environmentVariableSelector, configFileSelector, default: defaultValue }, configuration = {}) => {
    const { signingName, logger } = configuration;
    const envOptions = { signingName, logger };
    return memoize(chain(fromEnv(environmentVariableSelector, envOptions), fromSharedConfigFiles(configFileSelector, configuration), fromStatic(defaultValue)));
};
